using UnityEngine;

namespace LightMMORPG.Config
{
    public enum AbilityKind
    {
        Projectile,
        Beam,
        Buff
    }

    /// <summary>Data for one power. Generated by ProjectBuilder.BuildConfig into Assets/_Project/Data/Abilities.</summary>
    [CreateAssetMenu(menuName = "LightMMORPG/Ability Definition", fileName = "Ability")]
    public sealed class AbilityDefinition : ScriptableObject
    {
        [Header("Identity")]
        public string id;
        public string displayName;
        public AbilityKind kind;

        [Header("Cost")]
        public float energyCost;
        [Tooltip("Aura reserve spent per use. The reserve never refills during a battle (see Core.AuraReserve).")]
        public float auraCost;
        public float cooldown;

        [Header("Damage")]
        public float damageMin;
        public float damageMax;
        [Tooltip("Hold time for full charge (0 = not chargeable). Damage lerps min → max over it.")]
        public float maxChargeTime;

        [Header("Shape")]
        [Tooltip("Projectile speed (m/s).")]
        public float speed;
        public float radius;
        public float range;
        [Tooltip("Projectile lifetime or buff duration (s).")]
        public float duration;

        [Header("Buff multipliers (1 = none)")]
        public float damageMultiplier = 1f;
        public float speedMultiplier = 1f;
        public bool pausesEnergyRegen;

        /// <summary>Damage for a given charge time. Non-chargeable abilities return damageMax.</summary>
        public float DamageForCharge(float chargeTime)
        {
            if (maxChargeTime <= 0f) return damageMax;
            return Core.DamageCalculator.BeamDamage(chargeTime, damageMin, damageMax, maxChargeTime);
        }
    }
}
